const supabaseKey = process.env.REACT_APP_SUPABASE_ANON_KEY || "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImdkemxpZ3hyeW9kYXNheG5oZGNvIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODcxNTg1MDUsImV4cCI6MjEwMjczNDUwNX0.AYTyAMf22g8au51ATReRQdQc2IzDLYQ2vtQH_Uyfrpg";
const supabase = createClient(supabaseUrl, supabaseKey);

const CRMLeads = () => {
  const userStr = sessionStorage.getItem('dayal_user');
  const loggedInUser = userStr ? JSON.parse(userStr) : null;
  const isAdmin = loggedInUser?.role === 'Admin' || loggedInUser?.role === 'CRO';

  const [leads, setLeads] = useState([]);
   const [employeesMap, setEmployeesMap] = useState({});
  const [employeesGrouped, setEmployeesGrouped] = useState({});
  const [searchTerm, setSearchTerm] = useState("");
    const [currentPage, setCurrentPage] = useState(1);
  const [sortOrder, setSortOrder] = useState("newest");
  const [filterEmployee, setFilterEmployee] = useState("");
  const [filterService, setFilterService] = useState("");
      const [filterStartDate, setFilterStartDate] = useState("");
  const [filterEndDate, setFilterEndDate] = useState("");
  const [loading, setLoading] = useState(true);
  const [selectedLead, setSelectedLead] = useState(null);
  const lastCloseTime = useRef(0);
  const scrollPosRef = useRef(0);

  const [convertLeadData, setConvertLeadData] = useState(null);
  const [convertedCount, setConvertedCount] = useState(0);
  const [followupTodayCount, setFollowupTodayCount] = useState(0);
  const fileInputRef = useRef(null);
  const [importing, setImporting] = useState(false);

  const handleImport = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setImporting(true);
    try {
      const reader = new FileReader();
      reader.onload = async (evt) => {
        try {
          const data = evt.target.result;
          const workbook = XLSX.read(data, { type: 'binary' });
          const sheet = workbook.Sheets[workbook.SheetNames[0]];
          const json = XLSX.utils.sheet_to_json(sheet, { defval: "", raw: false }); // raw: false gets formatted date strings

          // Fetch employees to map "FOLLOW BY" correctly
          const { data: empData } = await supabase.from('employees').select('id, name');
          const empMap = {};
          if (empData) {
             empData.forEach(emp => {
                if (emp.name) {
                   empMap[emp.name.toLowerCase().trim()] = emp.id;
                }
             });
          }

          const leadInserts = [];
          const clientInserts = [];
          for (const row of json) {
             const clientName = row["CLIENT DETAILS"];
             if (!clientName) continue;
             
             const remarks = (row["REMARKS"] || "").toUpperCase().trim();
             
             let createdAt = new Date().toISOString();
             if (row["LEAD ARRIVING DATE"]) {
                 const parsed = new Date(row["LEAD ARRIVING DATE"]);
                 if (!isNaN(parsed)) createdAt = parsed.toISOString();
             }

             if (remarks === 'SUCCESS') {
                clientInserts.push({
                   name: clientName,
                   status: "Active",
                   created_at: createdAt
                   // Other fields like phone, email can be added if DB supports it or synced via localStorage later.
                });
             } else {
                 let leadTemp = "Cold";
                 let status = row["STATUS"] || "New";
                 const rawStatus = status.toUpperCase();
                 
                 if (rawStatus.includes("HOT")) { leadTemp = "Hot"; status = "New"; }
                 else if (rawStatus.includes("WARM")) { leadTemp = "Warm"; status = "New"; }
                 else if (rawStatus.includes("COLD")) { leadTemp = "Cold"; status = "New"; }
                 else if (remarks === 'CLOSED') { status = "Lost"; }
                 else if (remarks === 'ONGOING') { status = "Contacted"; }
                 
                 leadInserts.push({
                    name: clientName,
                    phone: row["PHONE NO."] || null,
                    address: row["ADDRESS"] || null,
                    source: row["SOURCE"] || null,
                    service_type: row["REQUIREMENT"] || null,
                    created_at: createdAt,
                    status: status,
                    lead_temperature: leadTemp,
                    assigned_to: row["FOLLOW BY"] || null,
                    notes: row["REMARKS"] || null
                 });
             }
          }
          
          let importCount = 0;
          if (leadInserts.length > 0) {
              const { error } = await supabase.from('leads').insert(leadInserts);
              if (error) alert("Lead Import failed: " + error.message);
              else importCount += leadInserts.length;
          }
          if (clientInserts.length > 0) {
              const { error } = await supabase.from('clients').insert(clientInserts);
              if (error) alert("Client Import failed: " + error.message);
              else {
                 importCount += clientInserts.length;
                 // Manually save localStorage data for the clients to retain phone/address since DB lacks it
                 // We don't have the inserted IDs here easily unless we select after, but we can do our best.
              }
          }
          
          if (importCount > 0) {
             alert(`Successfully imported ${importCount} records (${leadInserts.length} Leads, ${clientInserts.length} Clients)!`);
             fetchLeads();
          }
        } catch (innerErr) {
          alert("Parse error: " + innerErr.message);
        }
        setImporting(false);
        e.target.value = null; // reset input
      };
      reader.readAsBinaryString(file);
    } catch(err) {
      alert("Error reading file.");
      setImporting(false);
      e.target.value = null;
    }
  };

  const handleExport = () => {
      const dataToExport = leads.map(l => ({
         "CLIENT DETAILS": l.name,
         "ADDRESS": l.address || "",
         "PHONE NO.": l.phone || "",
         "SOURCE": l.source || "",
         "REQUIREMENT": l.service_type || "",
         "LEAD ARRIVING DATE": l.created_at ? new Date(l.created_at).toLocaleDateString('en-GB') : "",
         "STATUS": l.status,
         "TEMPERATURE": l.lead_temperature || "",
         "FOLLOW BY": l.assigned_to || "",
         "REMARKS": l.notes || ""
      }));
      const ws = XLSX.utils.json_to_sheet(dataToExport);
      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, "Leads");
      XLSX.writeFile(wb, "Leads_Export.xlsx");
  };


  const confirmConvert = async () => {
    if (!convertLeadData) return;
    
    let finalNotes = convertLeadData.notes || "";
    if (convertLeadData.whatsapp) finalNotes = `WhatsApp: ${convertLeadData.whatsapp}
${finalNotes}`;
    
    const { data: newClientData, error: insertError } = await supabase.from('clients').insert([{ 
       name: convertLeadData.name, 
       status: 'active', 
       email: convertLeadData.email, 
       phone: convertLeadData.phone, 
       address: convertLeadData.address, 
       company: convertLeadData.company || convertLeadData.name, 
       source: convertLeadData.source, 
       service_type: convertLeadData.service_type, 
       work_types: convertLeadData.service_type,
       lead_score: convertLeadData.lead_score, 
       budget: convertLeadData.budget, 
       plot_size: convertLeadData.plot_size, 
       timeline: convertLeadData.timeline, 
       lead_temperature: convertLeadData.lead_temperature, 
       notes: finalNotes 
    }]).select();

    if (!insertError && newClientData && newClientData.length > 0) {
       await supabase.from('leads').delete().eq('id', convertLeadData.id);
       setConvertLeadData(null);
       fetchLeads();
    } else {
       alert("Failed to convert to client.");
       setConvertLeadData(null);
    }
  };

  // Modals
  const [showNewLeadModal, setShowNewLeadModal] = useState(false);
  const [showStatusModal, setShowStatusModal] = useState(null); // stores lead object for status update
  const [statusUpdateData, setStatusUpdateData] = useState({ status: "New", lead_temperature: "Warm Lead", reason: "", followup: "" });
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(null); // stores lead object to delete
  const [activeMenu, setActiveMenu] = useState(null); // stores lead id for open menu

  // New Lead Form State
  const [newLead, setNewLead] = useState({
    name: "", phone: "", whatsapp: "", email: "", service_type: [], source: "", address: "", notes: "", status: "New", lead_temperature: "Warm Lead"
  });

  const fetchLeads = async (showLoader = true) => {
    if (showLoader) setLoading(true);
    let query = supabase.from("leads").select("*").order('created_at', { ascending: false });
    
    // User requested: "lead section should visible to all employee(update the permission)"
    // So we no longer restrict leads based on assigned_to.
    
    const { data, error } = await query;
    
    const now = new Date();
    const firstDayOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
    const { count: cCount } = await supabase.from('clients').select('*', { count: 'exact', head: true }).gte('created_at', firstDayOfMonth);
    if (cCount !== null) setConvertedCount(cCount);

    const todayStr = now.toISOString().split('T')[0];
    const { data: fuData } = await supabase.from('tasks').select('id, due_date, status').eq('custom_category', 'Follow Up').neq('status', 'Completed');
    if (fuData) {
       const dueToday = fuData.filter(f => f.due_date && f.due_date.split("T")[0] === todayStr).length;
       setFollowupTodayCount(dueToday);
    }
    if (!error && data) {
         const { data: empDataFetch } = await supabase.from("employees").select("id, name, designation, role");
         const eGrouped = { Admin: [], CRO: [], OAS: [], Engineers: [], Others: [] };
         if (empDataFetch) {
            empDataFetch.forEach(e => {
               const desig = (e.designation || "").toLowerCase();
               const role = (e.role || "").toLowerCase();
               if (role === "admin" || desig.includes("admin")) eGrouped.Admin.push(e);
               else if (role === "cro" || desig.includes("relationship")) eGrouped.CRO.push(e);
               else if (role === "oas" || desig.includes("oas")) eGrouped.OAS.push(e);
               else if (desig.includes("engineer")) eGrouped.Engineers.push(e);
               else eGrouped.Others.push(e);
            });
         }
         setEmployeesGrouped(eGrouped);
         const eMap = {};
         if (empDataFetch) { empDataFetch.forEach(e => eMap[e.id] = e.name); }
         setEmployeesMap(eMap);

       // Merge with localStorage
       const merged = data.map(lead => {
          
          return lead;
       });
         // Group duplicates by phone number
         const groupedMap = {};
         const finalLeads = [];
         merged.forEach(lead => {
            if (!lead.phone || lead.phone.trim() === "") {
               finalLeads.push(lead);
            } else {
               const phoneStr = lead.phone.trim();
               if (groupedMap[phoneStr]) {
                  const primary = groupedMap[phoneStr];
                  if (!primary.duplicate_history) primary.duplicate_history = [];
                  primary.duplicate_history.push(lead);
               } else {
                  groupedMap[phoneStr] = lead;
                  finalLeads.push(lead);
               }
            }
         });
         
         setLeads(finalLeads);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchLeads();
    const channel = supabase
      .channel('leads-realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'leads' }, () => {
        fetchLeads(false);
      })
      .subscribe();
    return () => supabase.removeChannel(channel);
  }, []);
  useEffect(() => {
    const handleReset = () => setSelectedLead(null); lastCloseTime.current = Date.now();
    window.addEventListener("reset-view", handleReset);
    return () => window.removeEventListener("reset-view", handleReset);
  }, []);

  const handleCreateLead = async (e) => {
    e.preventDefault();
    
    // OPTIMISTIC UI
    const tempId = `temp-${Date.now()}`;
    const mappedService = Array.isArray(newLead.service_type) ? newLead.service_type.join(', ') : newLead.service_type;
    const mappedSource = newLead.source === "Other" ? (newLead.source_custom || "Other") : newLead.source;
    
    const optimisticLead = {
       id: tempId,
       name: newLead.name,
       phone: newLead.phone,
       service_type: mappedService,
       source: mappedSource,
       status: newLead.status || "New",
       created_at: newLead.created_at ? new Date(newLead.created_at).toISOString() : new Date().toISOString()
    };
    
    

    setLeads([optimisticLead, ...leads]);
    setShowNewLeadModal(false);
    setNewLead({ name: "", phone: "", whatsapp: "", email: "", service_type: [], source: "", address: "", notes: "", status: "New" });

    // BACKGROUND SYNC
    const { data: newLeadData, error } = await supabase.from("leads").insert([{
       name: optimisticLead.name,
       phone: optimisticLead.phone,
       service_type: optimisticLead.service_type,
       source: optimisticLead.source,
       status: optimisticLead.status,
       created_at: optimisticLead.created_at
    }]).select();

    if (!error && newLeadData && newLeadData.length > 0) {
      const realId = newLeadData[0].id;
      const savedData = localStorage.getItem(`lead_${tempId}`);
      if (savedData) {
         localStorage.setItem(`lead_${realId}`, savedData);
         localStorage.removeItem(`lead_${tempId}`);
      }
      fetchLeads(false);
    } else {
      console.error("Error creating lead:", error);
      alert("Failed to create lead. Check console.");
      fetchLeads(false);
    }
  };

  const handleUpdateStatus = async () => {
    if (!showStatusModal) return;
    const leadId = showStatusModal.id;
    
    // Update DB
    const { error } = await supabase.from("leads").update({ status: statusUpdateData.status }).eq("id", leadId);
    if (!error) {
       // Also update localStorage with the temperature
       
       
       
       
       if (statusUpdateData.status === "Won") {
          const leadToConvert = leads.find(l => l.id === leadId);
          if (leadToConvert) {
             setConvertLeadData(leadToConvert);
          }
       }
       
       setShowStatusModal(null);
       fetchLeads();
    } else {
       alert("Error updating status: " + error.message);
    }
  };

  const handleDirectStatusChange = async (leadId, newStatus) => {
    const { error } = await supabase.from("leads").update({ status: newStatus }).eq("id", leadId);
    if (error) alert("Error: " + error.message);
    else {
      if (newStatus === "Success") {
        const leadToConvert = leads.find(l => l.id === leadId);
        if (leadToConvert) {
           setConvertLeadData(leadToConvert);
        }
      }
      fetchLeads();
    }
  };

  const handleDirectTempChange = async (leadId, newTemp) => {
    
    
    
    
    await supabase.from("leads").update({ lead_temperature: newTemp }).eq("id", leadId);
    fetchLeads();
  };

  const handleDeleteLead = async (id) => {
    // Optimistic UI
    setShowDeleteModal(null);
    setLeads(leads.filter(l => l.id !== id));
    localStorage.removeItem(`lead_${id}`);
    
    // Background Sync
    await supabase.from("leads").delete().eq("id", id);
    fetchLeads(false);
  };

  const getStatusColor = (status) => {
    switch(status) {
      case 'New': return 'bg-blue-100 text-blue-700';
      case 'Contacted': return 'bg-purple-100 text-purple-700';
      case 'Site Visit': return 'bg-cyan-100 text-cyan-700';
      case 'Estimate': return 'bg-orange-100 text-orange-700';
      case 'Negotiation': return 'bg-yellow-100 text-yellow-700';
      case 'Won': return 'bg-green-100 text-green-700';
      case 'Lost': return 'bg-red-100 text-red-700';
      default: return 'bg-gray-100 dark:bg-navy-700 text-gray-700 dark:text-gray-200';
    }
  };

  const getTempColor = (temp) => {
    switch(temp) {
      case 'Hot Lead': return 'bg-red-100 text-red-700';
      case 'Warm Lead': return 'bg-orange-100 text-orange-700';
      case 'Cold Lead': return 'bg-blue-100 text-blue-700';
      default: return 'bg-gray-100 dark:bg-navy-700 text-gray-700 dark:text-gray-200';
    }
  };

  return (
    <>
    {selectedLead && <LeadDetail lead={selectedLead} onBack={(updated) => { if(updated && updated.id){ setLeads(leads.map(l => l.id === updated.id ? updated : l)); } setSelectedLead(null); lastCloseTime.current = Date.now(); fetchLeads(false); }} />}
    <div className={`w-full max-w-full bg-[#F8FAFC] dark:bg-navy-900 h-auto pt-4 pb-8 ${selectedLead ? 'hidden' : 'block'}`}>
      {convertLeadData && (
        <div className="fixed inset-0 z-[99] flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-white dark:bg-navy-800 rounded-[20px] p-6 w-full max-w-md shadow-2xl transform transition-all">
             <div className="flex justify-between items-center mb-4">
               <h2 className="text-xl font-bold text-[#0F172A] dark:text-white">Convert to Client?</h2>
               <MdClose className="text-2xl text-[#64748B] dark:text-gray-400 cursor-pointer hover:text-red-500" onClick={() => setConvertLeadData(null)} />
             </div>
             <p className="text-[#475569] dark:text-gray-200 dark:text-white mb-6">You are marking <span className="font-bold text-[#0F172A] dark:text-white">{convertLeadData.name}</span> as "Won". Would you like to remove them from Leads and officially convert them into a Client?</p>
             <div className="flex gap-3 justify-end">
               <button onClick={() => setConvertLeadData(null)} className="px-5 py-2.5 rounded-[10px] font-bold text-[#475569] dark:text-gray-200 dark:text-white bg-gray-100 dark:bg-navy-700 hover:bg-gray-200 transition-colors">Cancel</button>
               <button onClick={confirmConvert} className="px-5 py-2.5 rounded-[10px] font-bold text-white bg-[#16A34A] hover:bg-green-700 transition-colors flex items-center gap-2"><MdCheckCircle /> Convert to Client</button>
             </div>
          </div>
        </div>
      )}
        <div className="max-w-[1180px] mx-auto px-4 sm:px-6 lg:px-8 font-sans text-[#475569] dark:text-gray-200 dark:text-white">
          <div className="pt-2 pb-4 -mx-4 px-4 sm:-mx-6 sm:px-6 lg:-mx-8 lg:px-8">
          {/* 1. Breadcrumb & Header */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-4 gap-4 mt-2 md:mt-0">
          <div>
            <p className="text-[12px] font-medium text-[#64748B] dark:text-gray-400 mb-1">Pages / Leads</p>
            <h1 className="text-[32px] font-bold text-[#0F172A] dark:text-white leading-tight">Leads Management</h1>
          </div>
          <div className="flex gap-3 z-10 relative">
            <input type="file" ref={fileInputRef} onChange={handleImport} accept=".csv, .xlsx, .xls" className="hidden" />
            <button onClick={() => fileInputRef.current.click()} disabled={importing} className="h-10 px-4 rounded-[12px] border border-[#E2E8F0] dark:border-navy-700 bg-white dark:bg-navy-800 text-[14px] font-bold text-[#0F172A] dark:text-white hover:bg-gray-50 dark:hover:bg-navy-800 flex items-center gap-2 transition disabled:opacity-50">
              <MdCloudDownload /> {importing ? "Importing..." : "Import Excel"}
            </button>
            <button onClick={handleExport} className="h-10 px-4 rounded-[12px] border border-[#E2E8F0] dark:border-navy-700 bg-white dark:bg-navy-800 text-[14px] font-bold text-[#0F172A] dark:text-white hover:bg-gray-50 dark:hover:bg-navy-800 flex items-center gap-2 transition">
              <MdCloudDownload /> Export Data
            </button>
            <button onClick={() => setShowNewLeadModal(true)} className="h-10 px-5 rounded-[12px] bg-[#2563EB] text-[14px] font-bold text-white hover:bg-[#1D4ED8] flex items-center gap-2 transition shadow-[0_2px_10px_rgba(37,99,235,0.2)]">
              <MdAdd /> New Lead
            </button>
          </div>
        </div>

        {/* 2. KPI Cards */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-1">
          {[
             { title: "Total Leads", val: leads.length || "0", icon: <MdPeople className="text-[#2563EB]" />, bg: "bg-blue-50" },
               { title: "Hot Leads", val: leads.filter(l => l.lead_temperature === 'Hot').length || "0", icon: <MdLocalFireDepartment className="text-[#DC2626]" />, bg: "bg-red-50" },
               { title: "Follow-up Today", val: followupTodayCount || "0", icon: <MdToday className="text-[#F59E0B]" />, bg: "bg-orange-50" },
               { title: "Converted This Month", val: convertedCount || "0", icon: <MdCheckCircle className="text-[#16A34A]" />, bg: "bg-green-50" }
            ].map((kpi, i) => (
              <Card key={i} extra="py-3 px-4 border border-[#E2E8F0] dark:border-navy-700 hover:-translate-y-1 hover:shadow-[0_8px_24px_rgba(15,23,42,0.08)] hover:border-blue-200 transition-all duration-300">
               <div className="flex justify-between items-start">
                  <div>
                    <p className="text-[12px] font-medium text-[#64748B] dark:text-gray-400 mb-1">{kpi.title}</p>
                    <p className="text-[28px] font-bold text-[#0F172A] dark:text-white leading-none">{kpi.val}</p>
                  </div>
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center text-xl ${kpi.bg}`}>
                     {kpi.icon}
                  </div>
               </div>
            </Card>
          ))}
        </div>

        </div> {/* Close Red Part */}
          {/* GREEN PART: STICKY WRAPPER */}
          <div className="sticky top-[60px] z-30 bg-[#F8FAFC] dark:bg-navy-900 pt-0 -mx-4 px-4 sm:-mx-6 sm:px-6 lg:-mx-8 lg:px-8 block pb-2">
          {/* 3. Search & Filter Toolbar */}
          <Card extra="shrink-0 p-3 border border-[#E2E8F0] dark:border-navy-700 mb-3 shadow-sm">
              <div className="flex flex-row justify-between items-center gap-4 w-full overflow-x-auto pb-1">
                <div className="relative flex-1 min-w-[200px] max-w-[400px]">
                  <MdSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[#64748B] dark:text-gray-400 text-xl" />
                  <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => { setSearchTerm(e.target.value); setCurrentPage(1); }} 
                    placeholder="Search name, phone, address..." 
                    className="w-full pl-10 pr-4 h-10 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] outline-none focus:border-[#2563EB] transition-colors" 
                  />
                </div>
                  <div className="flex gap-3 flex-nowrap items-center shrink-0">
                    <div className="flex items-center gap-1">
                       <input type="date" value={filterStartDate} onChange={(e) => { setFilterStartDate(e.target.value); setCurrentPage(1); }} className="h-10 px-2 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#475569] dark:text-gray-200 dark:text-white outline-none focus:border-[#2563EB] bg-transparent dark:bg-navy-900 cursor-pointer" title="Start Date" />
                       <span className="text-[#64748B] dark:text-gray-400 text-sm">to</span>
                       <input type="date" value={filterEndDate} onChange={(e) => { setFilterEndDate(e.target.value); setCurrentPage(1); }} className="h-10 px-2 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#475569] dark:text-gray-200 dark:text-white outline-none focus:border-[#2563EB] bg-transparent dark:bg-navy-900 cursor-pointer" title="End Date" />
                    </div>
                      <select 
                        value={filterEmployee}
                        onChange={(e) => { setFilterEmployee(e.target.value); setCurrentPage(1); }}
                        className="h-10 px-4 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#475569] dark:text-gray-200 dark:text-white outline-none focus:border-[#2563EB] bg-transparent dark:bg-navy-900 cursor-pointer w-[160px] truncate"
                        title="Filter by Employee"
                      >
                        <option value="">All Employees</option>
                        {Object.entries(employeesGrouped).map(([groupName, emps]) => {
                           if (!emps || emps.length === 0) return null;
                           return (
                              <optgroup key={groupName} label={groupName}>
                                 {emps.map(e => <option key={e.id} value={e.id}>{e.name}</option>)}
                              </optgroup>
                           );
                        })}
                      </select>

                      <select 
                        value={filterService}
                        onChange={(e) => { setFilterService(e.target.value); setCurrentPage(1); }}
                        className="h-10 px-4 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#475569] dark:text-gray-200 dark:text-white outline-none focus:border-[#2563EB] bg-transparent dark:bg-navy-900 cursor-pointer w-[160px] truncate"
                        title="Filter by Service"
                      >
                        <option value="">All Services</option>
                        <optgroup label="Design Services">
                           {DESIGN_SERVICES.map(s => <option key={s.id} value={s.id}>{s.id}</option>)}
                        </optgroup>
                        <optgroup label="Execution Projects">
                           {EXECUTION_PROJECTS.map(s => <option key={s.id} value={s.id}>{s.id}</option>)}
                        </optgroup>
                      </select>

                      <select 
                        value={sortOrder}
                        onChange={(e) => { setSortOrder(e.target.value); setCurrentPage(1); }}
                        className="h-10 px-4 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#475569] dark:text-gray-200 dark:text-white outline-none focus:border-[#2563EB] bg-transparent dark:bg-navy-900 cursor-pointer min-w-[140px]"
                      >
                        <optgroup label="Sort By">
                           <option value="newest">Newest First</option>
                           <option value="oldest">Oldest First</option>
                           <option value="name_asc">Name (A-Z)</option>
                           <option value="name_desc">Name (Z-A)</option>
                           <option value="status">Status (A-Z)</option>
                        </optgroup>
                        <optgroup label="Filter Status">
                           <option value="status_ongoing">Ongoing Leads</option>
                           <option value="status_success">Success Closed (Won)</option>
                        </optgroup>
                        <optgroup label="Filter Temp">
                           <option value="temp_hot">Hot Leads</option>
                           <option value="temp_warm">Warm Leads</option>
                           <option value="temp_cold">Cold Leads</option>
                        </optgroup>
                      </select>
                </div>
              </div>
              </Card>
        </div>


          {/* 4. Leads Data Table */}
        <Card extra="flex flex-col border border-[#E2E8F0] dark:border-navy-700 overflow-hidden shadow-sm">
          <div className="overflow-auto w-full max-h-[760px] custom-scrollbar">
            <table className="w-full text-left border-collapse min-w-[900px]">
              <thead className="sticky top-0 z-20 bg-[#F8FAFC] dark:bg-navy-900 shadow-sm">
                <tr className="bg-[#F8FAFC] dark:bg-navy-900 border-b border-[#E2E8F0] dark:border-navy-700">
                  <th className="py-2 px-6 w-12"><input type="checkbox" className="w-4 h-4 rounded text-[#2563EB] border-[#E2E8F0] dark:border-navy-700 cursor-pointer" /></th>
                  <th className="py-2 px-4 w-12 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider">Sl. No.</th>
                  <th className="py-2 px-4 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider">Lead</th>
                  <th className="py-2 px-4 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider">Source</th>
                  <th className="py-2 px-4 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider">Address</th>
                  <th className="py-2 px-4 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider">Service</th>
                  <th className="py-2 px-4 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider">Status</th>
                  <th className="py-2 px-4 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider">Temperature</th>
                  <th className="py-2 px-4 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider">Arriving Date</th>
                  <th className="py-2 px-4 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider">Assigned</th>
                  <th className="py-2 px-6 text-[12px] font-medium text-[#64748B] dark:text-gray-400 uppercase tracking-wider text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                  {(() => {
                     let filtered = leads;
                       if (filterStartDate) {
                          const start = new Date(filterStartDate);
                          start.setHours(0,0,0,0);
                          filtered = filtered.filter(x => x.created_at && new Date(x.created_at) >= start);
                       }
                       if (filterEndDate) {
                          const end = new Date(filterEndDate);
                          end.setHours(23,59,59,999);
                          filtered = filtered.filter(x => x.created_at && new Date(x.created_at) <= end);
                       }

                     if (filterEmployee) {
                        filtered = filtered.filter(x => x.assigned_to && x.assigned_to.includes(filterEmployee));
                     }
                     if (filterService) {
                        const search = filterService.toLowerCase();
                        filtered = filtered.filter(x => {
                           const types = (x.work_types || x.service_type || "").toLowerCase();
                           if (types.includes(search)) return true;
                           if (search.includes("mutation") && types.includes("mutation")) return true;
                           return false;
                        });
                     }

                     if (sortOrder === "status_ongoing") {
                        filtered = filtered.filter(x => x.status !== "Won" && x.status !== "Lost");
                     } else if (sortOrder === "status_success") {
                        filtered = filtered.filter(x => x.status === "Won");
                     } else if (sortOrder === "temp_hot") {
                        filtered = filtered.filter(x => x.lead_temperature === "Hot");
                     } else if (sortOrder === "temp_warm") {
                        filtered = filtered.filter(x => x.lead_temperature === "Warm");
                     } else if (sortOrder === "temp_cold") {
                        filtered = filtered.filter(x => x.lead_temperature === "Cold");
                     }
                     
                     if (sortOrder === "oldest") {
                        filtered.sort((a,b) => new Date(a.created_at) - new Date(b.created_at));
                     } else if (sortOrder === "name_asc") {
                        filtered.sort((a,b) => (a.name || "").localeCompare(b.name || ""));
                     } else if (sortOrder === "name_desc") {
                        filtered.sort((a,b) => (b.name || "").localeCompare(a.name || ""));
                     } else if (sortOrder === "status") {
                        filtered.sort((a,b) => (a.status || "").localeCompare(b.status || ""));
                     } else {
                        filtered.sort((a,b) => new Date(b.created_at) - new Date(a.created_at));
                     }
                     if (searchTerm) {
                        const lower = String(searchTerm).toLowerCase();
                        filtered = filtered.filter(l => 
                           (l.name && String(l.name).toLowerCase().includes(lower)) || 
                           (l.email && String(l.email).toLowerCase().includes(lower)) || 
                           (l.phone && String(l.phone).toLowerCase().includes(lower)) || 
                           (l.whatsapp && String(l.whatsapp).toLowerCase().includes(lower)) || 
                           (l.company && String(l.company).toLowerCase().includes(lower)) ||
                           (l.address && String(l.address).toLowerCase().includes(lower)) ||
                           (l.source && String(l.source).toLowerCase().includes(lower)) ||
                           (l.notes && String(l.notes).toLowerCase().includes(lower))
                        );
                     }
                     if (loading) return <tr><td colSpan="11" className="py-12 text-center text-gray-500">Loading leads...</td></tr>;
                     if (filtered.length === 0) return <tr><td colSpan="11" className="py-12 text-center text-gray-500">No leads found.</td></tr>;
                     const paginated = filtered;
                     return paginated.map((lead, index) => (
                        <tr key={lead.id} className="border-b border-gray-100 hover:bg-gray-50 dark:hover:bg-navy-800 cursor-pointer" onClick={() => { if (Date.now() - lastCloseTime.current < 500) return; setSelectedLead(lead); }}>
                           <td className="py-2 px-6" onClick={(e) => e.stopPropagation()}>
                              <input type="checkbox" className="w-4 h-4 rounded text-[#2563EB] border-[#E2E8F0] dark:border-navy-700 cursor-pointer" />
                           </td>
                               <td className="py-2 px-4 text-sm text-gray-800 font-bold">
                                  {filtered.length - ((currentPage - 1) * 10 + index)}
                               </td>
                           <td className="py-2 px-4">
                              <p className="text-sm text-gray-800 font-bold">{lead.name}</p>
                              {lead.email && <p className="text-[12px] text-gray-500">{lead.email}</p>}
                           </td>
                           <td className="py-2 px-4 text-sm text-gray-600">{lead.source || lead.phone || "-"}</td>
                            <td className="py-2 px-4 text-sm text-gray-600 truncate max-w-[150px]" title={lead.address || ""}>{lead.address || "-"}</td>
                           <td className="py-2 px-4 text-sm text-gray-600">{lead.service_type || "-"}</td>
                           <td className="py-2 px-4 text-sm">
                              <span className={`px-3 py-1 rounded-full text-xs font-bold ${lead.status === 'New' ? 'bg-blue-100 text-blue-700' : (lead.status === 'Ongoing' || lead.status === 'Contacted') ? 'bg-yellow-100 text-yellow-700' : lead.status === 'Converted' ? 'bg-green-100 text-green-700' : lead.status === 'Closed' ? 'bg-red-100 text-red-700' : 'bg-gray-100 dark:bg-navy-700 text-gray-600'}`}>
                                 {lead.status}
                              </span>
                           </td>
                           <td className="py-2 px-4 text-sm text-gray-600 font-medium">
                              {lead.lead_temperature === 'Hot' ? <span className="text-red-500 flex items-center gap-1"><MdLocalFireDepartment /> Hot</span> : 
                               lead.lead_temperature === 'Warm' ? <span className="text-orange-500">Warm</span> : 
                               lead.lead_temperature === 'Cold' ? <span className="text-blue-500">Cold</span> : "-"}
                           </td>
                           <td className="py-2 px-4 text-sm text-gray-600">{lead.created_at ? new Date(lead.created_at).toLocaleDateString('en-GB') : "-"}</td>
                           <td className="py-2 px-4 text-sm font-medium text-gray-800">
                              {lead.assigned_to ? (lead.assigned_to.split(",").filter(Boolean).map(id => employeesMap[id.trim()] || (id.includes("-") ? `EMP-${id.substring(0, 5).toUpperCase()}` : id)).join(", ")) : "Unassigned"}
                           </td>
                           <td className="py-2 px-6 text-right">
                               {isAdmin && (
                                 <button onClick={(e) => { e.stopPropagation(); handleDeleteLead(lead.id); }} className="text-red-500 hover:bg-red-50 p-2 rounded-lg transition" title="Delete Lead">
                                    <MdDeleteOutline size={20} />
                                 </button>
                               )}
                           </td>
                        </tr>
                     ));
                  })()}
               </tbody>
            </table>
          </div>
          </Card>
        

        </div>

        {/* New Lead Modal */}
      {showNewLeadModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="w-full max-w-[600px] bg-white dark:bg-navy-800 rounded-[20px] shadow-[0_20px_60px_rgba(15,23,42,0.2)] flex flex-col max-h-[90vh] animate-fade-in">
            <div className="p-6 border-b border-[#E2E8F0] dark:border-navy-700 flex justify-between items-center bg-white dark:bg-navy-800 rounded-t-[20px]">
              <h2 className="text-[20px] font-bold text-[#0F172A] dark:text-white">New Lead</h2>
            </div>
            <div className="p-6 overflow-y-auto flex-1 bg-white dark:bg-navy-800">
              <form id="newLeadForm" onSubmit={handleCreateLead} className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="md:col-span-2">
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase tracking-wide">Full Name</label>
                  <input required value={newLead.name} onChange={e=>setNewLead({...newLead, name: e.target.value})} type="text" placeholder="Enter full name" className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB] transition-colors" />
                </div>
                <div>
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase tracking-wide">Phone Number</label>
                  <input value={newLead.phone} onChange={e=>setNewLead({...newLead, phone: e.target.value})} type="text" placeholder="Enter phone" className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB] transition-colors" />
                </div>
                <div>
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase tracking-wide">WhatsApp</label>
                  <input value={newLead.whatsapp} onChange={e=>setNewLead({...newLead, whatsapp: e.target.value})} type="text" placeholder="Enter WhatsApp" className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB] transition-colors" />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase tracking-wide">Email Address</label>
                  <input value={newLead.email} onChange={e=>setNewLead({...newLead, email: e.target.value})} type="email" placeholder="Enter email" className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB] transition-colors" />
                </div>
                <div>
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase tracking-wide">Service</label>
                  <div className="flex flex-col gap-2 max-h-48 overflow-y-auto p-2 border rounded-[10px] dark:border-navy-700 custom-scrollbar">
                        <div className="text-xs font-bold text-brand-500 mb-1">Services</div>
                        {DESIGN_SERVICES.map(s => (
                           <label key={s.id} className="flex items-center gap-2 text-sm cursor-pointer hover:bg-gray-50 dark:hover:bg-navy-700 p-1 rounded">
                              <input type="checkbox" checked={Array.isArray(newLead.service_type) && newLead.service_type.includes(s.id)} onChange={(e) => {
                                 let st = Array.isArray(newLead.service_type) ? [...newLead.service_type] : [];
                                 if (e.target.checked) st.push(s.id);
                                 else st = st.filter(x => x !== s.id);
                                 setNewLead({...newLead, service_type: st});
                              }} /> {s.id}
                           </label>
                        ))}
                        <div className="text-xs font-bold text-brand-500 mt-2 mb-1">Projects</div>
                        {EXECUTION_PROJECTS.map(p => (
                           <label key={p.id} className="flex items-center gap-2 text-sm cursor-pointer hover:bg-gray-50 dark:hover:bg-navy-700 p-1 rounded">
                              <input type="checkbox" checked={Array.isArray(newLead.service_type) && newLead.service_type.includes(p.id)} onChange={(e) => {
                                 let st = Array.isArray(newLead.service_type) ? [...newLead.service_type] : [];
                                 if (e.target.checked) st.push(p.id);
                                 else st = st.filter(x => x !== p.id);
                                 setNewLead({...newLead, service_type: st});
                              }} /> {p.id}
                           </label>
                        ))}
                    </div>
                </div>
                <div>
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase tracking-wide">Lead Source</label>
                  <select value={newLead.source} onChange={e=>setNewLead({...newLead, source: e.target.value})} className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB] transition-colors cursor-pointer bg-white dark:bg-navy-800">
                                        <option value="">Select source...</option>
                    <option value="Website">Website</option>
                    <option value="Referral">Referral</option>
                    <option value="Walk-in">Walk-in</option>
                    <option value="Phone Call">Phone Call</option>
                    <option value="WhatsApp">WhatsApp</option>
                    <option value="JustDial">JustDial</option>
                    <option value="Sulekha">Sulekha</option>
                    <option value="IndiaMart">IndiaMart</option>
                    <option value="Google Ads">Google Ads</option>
                    <option value="Google Maps (GMB)">Google Maps (GMB)</option>
                    <option value="Instagram">Instagram</option>
                    <option value="Facebook">Facebook</option>
                    <option value="LinkedIn">LinkedIn</option>
                    <option value="YouTube">YouTube</option>
                    <option value="BNI">BNI</option>
                    <option value="Real Estate Brokers">Real Estate Brokers</option>
                    <option value="Site Signage / Hoardings">Site Signage / Hoardings</option>
                    <option value="Print Ads / Newspaper">Print Ads / Newspaper</option>
                    <option value="Repeat Client">Repeat Client</option>
                    <option value="Cold Calling">Cold Calling</option>
                    <option value="Other">Other</option>
                  </select>
                  {newLead.source === "Other" && (
                    <input type="text" placeholder="Please specify..." onChange={e => setNewLead({...newLead, source_custom: e.target.value})} className="w-full h-11 px-3 mt-2 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB] transition-colors" />
                  )}
                </div>
                <div className="md:col-span-2">
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase tracking-wide">Arriving Date</label>
                  <input type="date" value={newLead.created_at || ""} onChange={e=>setNewLead({...newLead, created_at: e.target.value})} className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB] transition-colors" />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase tracking-wide">Address / Location</label>
                  <input value={newLead.address} onChange={e=>setNewLead({...newLead, address: e.target.value})} type="text" placeholder="Enter location" className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB] transition-colors" />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase tracking-wide">Initial Notes</label>
                  <textarea value={newLead.notes} onChange={e=>setNewLead({...newLead, notes: e.target.value})} placeholder="Enter any specific requirements..." className="w-full min-h-[100px] p-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB] transition-colors resize-y"></textarea>
                </div>
              </form>
            </div>
            <div className="p-6 border-t border-[#E2E8F0] dark:border-navy-700 flex justify-end gap-3 bg-[#F8FAFC] dark:bg-navy-900 rounded-b-[20px]">
              <button onClick={() => setShowNewLeadModal(false)} className="h-10 px-6 rounded-[12px] border border-[#E2E8F0] dark:border-navy-700 bg-white dark:bg-navy-800 text-[14px] font-bold text-[#475569] dark:text-gray-200 dark:text-white hover:bg-gray-100 dark:bg-navy-700 hover:text-[#0F172A] dark:text-white transition">Cancel</button>
              <button form="newLeadForm" type="submit" className="h-10 px-6 rounded-[12px] bg-[#2563EB] text-[14px] font-bold text-white hover:bg-[#1D4ED8] transition shadow-md">Create Lead</button>
            </div>
          </div>
        </div>
      )}

      {/* Change Status Modal Placeholder */}
      {showStatusModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="w-full max-w-[400px] bg-white dark:bg-navy-800 rounded-[20px] shadow-2xl p-6">
            <h2 className="text-[20px] font-bold text-[#0F172A] dark:text-white mb-4">Change Status</h2>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase">New Status</label>
                  <select 
                    value={statusUpdateData.status} 
                    onChange={e => setStatusUpdateData({...statusUpdateData, status: e.target.value})}
                    className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB]"
                  >
                    <option>Ongoing</option>
                    
                    <option>Success</option>
                    <option>Estimate</option>
                    <option>Negotiation</option>
                    
                    <option>Closed</option>
                  </select>
                </div>
                <div>
                  <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase">Temperature</label>
                  <select 
                    value={statusUpdateData.lead_temperature} 
                    onChange={e => setStatusUpdateData({...statusUpdateData, lead_temperature: e.target.value})}
                    className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB]"
                  >
                    <option>Hot Lead</option>
                    <option>Warm Lead</option>
                    <option>Cold Lead</option>
                  </select>
                </div>
              </div>
              <div>
                <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase">Reason</label>
                <textarea 
                  value={statusUpdateData.reason}
                  onChange={e => setStatusUpdateData({...statusUpdateData, reason: e.target.value})}
                  placeholder="Enter reason..." 
                  className="w-full h-20 p-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB]"></textarea>
              </div>
              <div>
                <label className="block text-[12px] font-bold text-[#475569] dark:text-gray-200 dark:text-white mb-1.5 uppercase">Next Follow-up</label>
                <input 
                  type="date" 
                  value={statusUpdateData.followup}
                  onChange={e => setStatusUpdateData({...statusUpdateData, followup: e.target.value})}
                  className="w-full h-11 px-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] text-[#0F172A] dark:text-white outline-none focus:border-[#2563EB]" />
              </div>
              <div className="flex items-center gap-2">
                <input type="checkbox" id="notify" className="w-4 h-4 rounded text-[#2563EB] border-[#E2E8F0] dark:border-navy-700" />
                <label htmlFor="notify" className="text-[13px] text-[#475569] dark:text-gray-200 dark:text-white">Notify Assigned Executive</label>
              </div>
            </div>
            <div className="mt-6 flex justify-end gap-3">
              <button onClick={() => setShowStatusModal(null)} className="h-10 px-6 rounded-[12px] border border-[#E2E8F0] dark:border-navy-700 bg-white dark:bg-navy-800 text-[14px] font-bold text-[#475569] dark:text-gray-200 dark:text-white hover:bg-gray-100 dark:bg-navy-700 transition">Cancel</button>
              <button onClick={handleUpdateStatus} className="h-10 px-6 rounded-[12px] bg-[#2563EB] text-[14px] font-bold text-white hover:bg-[#1D4ED8] transition">Update Status</button>
            </div>
          </div>
        </div>
      )}

      {/* Assign Executive Modal Placeholder */}
      {showAssignModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="w-full max-w-[400px] bg-white dark:bg-navy-800 rounded-[20px] shadow-2xl p-6">
            <h2 className="text-[20px] font-bold text-[#0F172A] dark:text-white mb-4">Assign Executive</h2>
            <div className="relative mb-4">
              <MdSearch className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[#64748B] dark:text-gray-400 text-xl" />
              <input type="text" placeholder="Search employee..." className="w-full pl-10 pr-4 h-11 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 text-[14px] outline-none focus:border-[#2563EB]" />
            </div>
            <div className="space-y-2 mb-6 max-h-[200px] overflow-y-auto">
              <div className="p-3 rounded-[10px] border border-[#E2E8F0] dark:border-navy-700 flex items-center gap-3 cursor-pointer hover:border-[#2563EB]">
                <div className="w-8 h-8 rounded-full bg-blue-100 flex items-center justify-center font-bold text-blue-600 text-[12px]">JS</div>
                <div>
                  <p className="text-[14px] font-bold text-[#0F172A] dark:text-white">John Smith</p>
                  <p className="text-[12px] text-[#64748B] dark:text-gray-400">Senior Sales Executive</p>
                </div>
              </div>
              {/* More employees can go here */}
            </div>
            <div className="flex justify-end gap-3">
              <button onClick={() => setShowAssignModal(false)} className="h-10 px-6 rounded-[12px] border border-[#E2E8F0] dark:border-navy-700 bg-white dark:bg-navy-800 text-[14px] font-bold text-[#475569] dark:text-gray-200 dark:text-white hover:bg-gray-100 dark:bg-navy-700 transition">Cancel</button>
              <button onClick={() => setShowAssignModal(false)} className="h-10 px-6 rounded-[12px] bg-[#2563EB] text-[14px] font-bold text-white hover:bg-[#1D4ED8] transition">Assign</button>
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4">
          <div className="w-full max-w-[400px] bg-white dark:bg-navy-800 rounded-[20px] shadow-[0_20px_60px_rgba(15,23,42,0.2)] p-6 text-center animate-fade-in">
            <div className="w-16 h-16 rounded-full bg-red-50 flex items-center justify-center text-[#DC2626] text-3xl mx-auto mb-4">
              <MdDeleteOutline />
            </div>
            <h2 className="text-[20px] font-bold text-[#0F172A] dark:text-white mb-2">Delete Lead?</h2>
            <p className="text-[14px] text-[#64748B] dark:text-gray-400 mb-6">Are you sure you want to delete <strong>{showDeleteModal.name}</strong>? This action cannot be undone.</p>
            <div className="flex justify-center gap-3">
              <button onClick={() => setShowDeleteModal(null)} className="flex-1 h-11 rounded-[12px] border border-[#E2E8F0] dark:border-navy-700 bg-white dark:bg-navy-800 text-[14px] font-bold text-[#475569] dark:text-gray-200 dark:text-white hover:bg-gray-100 dark:bg-navy-700 transition">Cancel</button>
              <button onClick={() => handleDeleteLead(showDeleteModal.id)} className="flex-1 h-11 rounded-[12px] bg-[#DC2626] text-[14px] font-bold text-white hover:bg-red-700 transition shadow-md">Delete Lead</button>
            </div>
          </div>
        </div>
      )}

    </div>
    </>
  );
};

export default CRMLeads;
